"""Score only after all 60 KiPERT predictions are sealed; retain comparator scores."""
from kipert_double import *
import ast,datetime
from scipy import stats
assert (E/'ALL_PREDICTIONS_SEALED.json').exists()
tree=ast.parse((R/'src/score_seen.py').read_text());exec(compile(ast.Module(body=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name in ['load','moments']],type_ignores=[]),'original_score_helpers','exec'))
O=E/'reports';O.mkdir(exist_ok=True);old=pd.read_json(R/'reports/final/query_metrics.json');rows=[];replay=[]
for ds in ['D1','D2','D3','D4']:
 for fold in range(5):
  base=R/f'data/formal/{ds}/seen0/fold{fold}';truth=load('evaluation_only',base);ctrl={c:v for (t,c),v in load('controls_score',base).items()};train=load('fit',base);mean={c:np.mean([v for (t,cc),v in train.items() if cc==c and '+' in t],axis=0) for c in ctrl};tmom=moments('evaluation_only',base);cmom={c:v for (t,c),v in moments('controls_score',base).items()};deg={}
  for k,(mu,var,n) in tmom.items():
   cc,vv,nn=cmom[k[1]];pv=stats.ttest_ind_from_stats(mu,np.sqrt(var),n,cc,np.sqrt(vv),nn,equal_var=False).pvalue;pv=np.nan_to_num(pv,nan=1.);deg[k]=np.lexsort((np.arange(len(mu)),-np.abs(mu-cc),pv))[:100]
  for arm in ['seen0','seen1','seen2']:
   folder=E/f'runs/{ds}/fold{fold}/{arm}';file=folder/'predictions_sealed.npz';result=json.loads((folder/'result.json').read_text());assert sha(file)==result['prediction_sha256'];z=np.load(file);ts=z['target'].astype(str);cs=z['context'].astype(str);pred=np.maximum(z['prediction'].astype(float),0);keys=list(zip(ts,cs));assert len(keys)==len(set(keys)) and set(keys)==set(truth)
   y=np.stack([truth[k] for k in keys]);cm=np.stack([ctrl[c] for c in cs]);tm=np.stack([mean[c] for c in cs]);mse=np.mean((pred-y)**2,axis=1);aa=pred-cm;bb=y-cm;aa-=aa.mean(1,keepdims=True);bb-=bb.mean(1,keepdims=True);den=np.linalg.norm(aa,axis=1)*np.linalg.norm(bb,axis=1);pcc=np.divide(np.sum(aa*bb,axis=1),den,out=np.full(len(den),np.nan),where=den>1e-15);mrr=np.full(len(ts),np.nan)
   for c in sorted(set(cs)):
    ix=np.flatnonzero(cs==c);a0=pred[ix]-tm[ix];b0=y[ix]-tm[ix];den=np.linalg.norm(a0,axis=1)[:,None]*np.linalg.norm(b0,axis=1)[None,:];sim=np.divide(a0@b0.T,den,out=np.zeros_like(den),where=den>1e-15)
    for k,ii in enumerate(ix):
     value=sim[k,k];better=int(sum(sim[k]>value+1e-12));ties=int(sum(abs(sim[k]-value)<=1e-12));mrr[ii]=float(np.mean(1/np.arange(better+1,better+ties+1)))
   for i,(t,c) in enumerate(keys):
    ix=deg[t,c];rows.append(dict(dataset=ds,fold=fold,arm=arm,seed=17,model='kipert',target=t,context=c,mse=float(mse[i]),pcc_delta=float(pcc[i]),specific_mrr=float(mrr[i]),posthoc_deg100_mse=float(np.mean((pred[i,ix]-y[i,ix])**2)),posthoc_deg100_sign=float(np.mean(np.sign(pred[i,ix]-cm[i,ix])==np.sign(y[i,ix]-cm[i,ix])))))
   oz=np.load(R/f'runs/formal/{ds}/{arm}/fold{fold}/seed17/uc/predictions_sealed.npz');np.testing.assert_array_equal(oz['target'],ts);np.testing.assert_array_equal(oz['context'],cs);omse=np.mean((np.maximum(oz['prediction'].astype(float),0)-y)**2,axis=1);ref=old[(old.dataset==ds)&(old.fold==fold)&(old.arm==arm)&(old.model=='uc')].set_index(['target','context']).loc[keys];err=float(np.max(abs(omse-ref.mse.to_numpy())));assert err<1e-8;replay.append(dict(dataset=ds,fold=fold,arm=arm,old_score_max_error=err))
  print('SCORED',ds,fold,flush=True)
new=pd.DataFrame(rows);keys=['dataset','fold','arm','seed','target','context'];assert len(new)==len(old[old.model=='uc']);assert set(map(tuple,new[keys].to_numpy()))==set(map(tuple,old[old.model=='uc'][keys].to_numpy()))
updated=pd.concat([old[old.model!='uc'],new],ignore_index=True);metriccols=['mse','pcc_delta','specific_mrr','posthoc_deg100_mse','posthoc_deg100_sign']
pair=new.groupby(['dataset','fold','arm','seed','model','target'],as_index=False)[metriccols].mean();macro=pair.groupby(['dataset','fold','arm','seed','model'],as_index=False)[metriccols].mean();oldmacro=pd.read_json(R/'reports/final/fold_metrics.json');extra_cols=['posthoc_deg100_mse','posthoc_deg100_sign'];oldextra=old.groupby(['dataset','fold','arm','seed','model','target'],as_index=False)[extra_cols].mean().groupby(['dataset','fold','arm','seed','model'],as_index=False)[extra_cols].mean();oldmacro=oldmacro.merge(oldextra,on=['dataset','fold','arm','seed','model'],validate='one_to_one');den=oldmacro[oldmacro.model=='no_change'][['dataset','fold','arm','no_change_mse']];macro=macro.merge(den,on=['dataset','fold','arm'],validate='many_to_one');macro['nmse']=macro.mse/macro.no_change_mse;add=oldmacro[oldmacro.model=='available_evidence_additive'][['dataset','fold','arm','mse']].rename(columns={'mse':'additive_mse'});macro=macro.merge(add,on=['dataset','fold','arm'],validate='many_to_one');macro['gain_vs_additive']=macro.additive_mse-macro.mse
newsummary=macro.groupby(['dataset','arm','model'],as_index=False)[metriccols+['nmse','gain_vs_additive']].mean();oldsummary=pd.read_json(R/'reports/final/summary_metrics.json');oldsummary=oldsummary.merge(oldextra.groupby(['dataset','arm','model'],as_index=False)[extra_cols].mean(),on=['dataset','arm','model'],validate='one_to_one');summary=pd.concat([oldsummary[oldsummary.model!='uc'],newsummary],ignore_index=True);folds=pd.concat([oldmacro[oldmacro.model!='uc'],macro],ignore_index=True)
comparison=oldsummary[oldsummary.model=='uc'].drop(columns='model').merge(newsummary.drop(columns='model'),on=['dataset','arm'],suffixes=('_old','_kipert'));comparison['nmse_delta']=comparison.nmse_kipert-comparison.nmse_old;comparison['mse_change_pct']=100*(comparison.mse_kipert/comparison.mse_old-1)
join=old[old.model=='uc'].merge(new,on=keys,suffixes=('_old','_kipert'),validate='one_to_one');join=join.merge(den,on=['dataset','fold','arm'],validate='many_to_one');join['delta_nmse']=(join.mse_kipert-join.mse_old)/join.no_change_mse;paired=join.groupby(['dataset','fold','arm','target'],as_index=False).delta_nmse.mean().groupby(['dataset','arm','target'],as_index=False).delta_nmse.mean();boot=[];rng=np.random.default_rng(20261106)
for (ds,arm),frame in paired.groupby(['dataset','arm']):
 v=frame.delta_nmse.to_numpy();n=len(v);b=np.mean(v[rng.integers(0,n,(10000,n))],axis=1);null=(rng.choice([-1.,1.],(10000,n))*v).mean(1);p=(1+sum(abs(null)>=abs(v.mean())))/10001;lo,hi=np.quantile(b,[.025,.975]);boot.append(dict(dataset=ds,arm=arm,targets=n,paired_target_delta_nmse=float(v.mean()),ci_low=float(lo),ci_high=float(hi),p_signflip=float(p)))
bf=pd.DataFrame(boot);order=np.argsort(bf.p_signflip.to_numpy());adjusted=np.maximum.accumulate(np.minimum(1,bf.p_signflip.to_numpy()[order]*(len(bf)-np.arange(len(bf)))));bf.loc[bf.index[order],'p_holm12']=adjusted;comparison=comparison.merge(bf,on=['dataset','arm'],validate='one_to_one')
for name,frame in [('query_metrics',updated),('kipert_query_metrics',new),('kipert_pair_metrics',pair),('fold_metrics',folds),('summary_metrics',summary),('old_new_comparison',comparison),('paired_target_differences',paired)]:
 (O/(name+'.json')).write_text(frame.to_json(orient='records',indent=2));frame.to_csv(O/(name+'.csv'),index=False)
oldpair=pd.read_json(R/'reports/final/pair_metrics.json');allpair=pd.concat([oldpair[oldpair.model!='uc'],pair],ignore_index=True);sm=allpair.groupby(['dataset','fold','arm','model','target'],as_index=False).mse.mean();wide=sm.pivot(index=['dataset','fold','model','target'],columns='arm',values='mse').reset_index();wide['gain01']=wide.seen0-wide.seen1;wide['gain12']=wide.seen1-wide.seen2;(O/'paired_information_gains.json').write_text(wide.to_json(orient='records',indent=2));oldmacro[oldmacro.model=='uc'].to_csv(O/'old_uc_fold_metrics.csv',index=False)
assert old[old.model!='uc'].reset_index(drop=True).equals(updated[updated.model!='kipert'].reset_index(drop=True))
hashes=json.loads((E/'provenance/original_hashes.json').read_text());assert all(sha(Path(p))==h for p,h in hashes.items());snapshot=json.loads((E/'provenance/original_prediction_stats.json').read_text());assert all([Path(p).stat().st_size,Path(p).stat().st_mtime_ns]==v for p,v in snapshot.items());save(O/'EVALUATION_QA.json',dict(status='PASS',old_score_replays=replay,other_method_rows_unchanged=int(sum(old.model!='uc')),all_original_result_hashes_unchanged=True,original_prediction_files_unchanged=len(snapshot),kiPERT_query_rows=len(new),scope='Exact source sparse means and original scorer definitions; no comparator recomputation or filtering'));save(O/'COMPLETE.json',dict(status='COMPLETE',new_runs=60,all_prediction_sets_in_updated_benchmark=len(folds),registered_jobs_in_original_benchmark=1020,generated_utc=datetime.datetime.now(datetime.timezone.utc).isoformat()));print(comparison[['dataset','arm','nmse_old','nmse_kipert','mse_change_pct']].to_string(index=False),flush=True)
